'use strict';

import { inject, injectable } from 'inversify';
import { env, UIKind } from 'vscode';
import { IApplicationEnvironment, IApplicationShell } from '../common/application/types';
import '../common/extensions';
import { Experiments } from '../common/experiments/groups';
import { IBrowserService, IExperimentService, IJupyterExtensionBanner, IPersistentStateFactory } from '../common/types';
import * as localize from '../common/utils/localize';
import { INotebookEditorProvider } from './types';

export enum InsidersNativeNotebooksStateKeys {
    ShowBanner = 'ShowInsidersNativeNotebooksSurveyBanner',
    OpenNotebookCount = 'InsidersNativeNotebooksOpenNotebookCount',
    ExecutionCount = 'InsidersNativeNotebooksExecutionCount'
}

enum InsidersNativeNotebooksSurveyLabelIndex {
    Yes,
    No
}

const NotebookOpenThreshold = 5;
const NotebookExecutionThreshold = 100;
const InsidersDelayUntilNotified = 1000 * 60 * 60 * 24 * 30;
const DsSurveyUrl = 'https://aka.ms/vscjupyternb';

@injectable()
export class InsidersNativeNotebooksSurveyBanner implements IJupyterExtensionBanner {
    private disabledInCurrentSession: boolean = false;
    private isInitialized: boolean = false;
    private bannerMessage: string = localize.InsidersNativeNotebooksSurveyBanner.bannerMessage();
    private bannerLabels: string[] = [
        localize.DataScienceSurveyBanner.bannerLabelYes(),
        localize.DataScienceSurveyBanner.bannerLabelNo()
    ];
    private readonly surveyLink: string;

    constructor(
        @inject(IApplicationShell) private appShell: IApplicationShell,
        @inject(IPersistentStateFactory) private persistentState: IPersistentStateFactory,
        @inject(IBrowserService) private browserService: IBrowserService,
        @inject(IExperimentService) private experimentService: IExperimentService,
        @inject(IApplicationEnvironment) private appEnvironment: IApplicationEnvironment,
        @inject(INotebookEditorProvider) editorProvider: INotebookEditorProvider,
        surveyLink: string = DsSurveyUrl
    ) {
        this.surveyLink = surveyLink;
        this.initialize();
        editorProvider.onDidOpenNotebookEditor(this.openedNotebook.bind(this));
    }

    public initialize(): void {
        if (this.isInitialized) {
            return;
        }
        this.isInitialized = true;
    }

    public get enabled(): boolean {
        return (
            this.appEnvironment.channel === 'insiders' &&
            this.persistentState
                .createGlobalPersistentState<boolean>(
                    InsidersNativeNotebooksStateKeys.ShowBanner,
                    true,
                    InsidersDelayUntilNotified
                )
                .value &&
            env.uiKind !== UIKind?.Web
        );
    }

    public async showBanner(): Promise<void> {
        if (!this.enabled || this.disabledInCurrentSession) {
            return;
        }

        const executionCount: number = this.getExecutionCount();
        const notebookCount: number = this.getOpenNotebookCount();
        const show = await this.shouldShowBanner(executionCount, notebookCount);
        if (!show) {
            return;
        }

        const response = await this.appShell.showInformationMessage(this.bannerMessage, ...this.bannerLabels);
        switch (response) {
            case this.bannerLabels[InsidersNativeNotebooksSurveyLabelIndex.Yes]: {
                await this.launchSurvey();
                await this.disable(6);
                break;
            }
            case this.bannerLabels[InsidersNativeNotebooksSurveyLabelIndex.No]: {
                await this.disable(3);
                break;
            }
            default: {
                // Disable for the current session.
                this.disabledInCurrentSession = true;
            }
        }
    }

    public async shouldShowBanner(executionCount: number, notebookOpenCount: number): Promise<boolean> {
        if (!this.enabled || this.disabledInCurrentSession) {
            return false;
        }

        return (
            (executionCount >= NotebookExecutionThreshold || notebookOpenCount > NotebookOpenThreshold) &&
            (await this.experimentService.inExperiment(Experiments.NativeNotebook))
        );
    }

    public async disable(months: number): Promise<void> {
        await this.persistentState
            .createGlobalPersistentState<boolean>(
                InsidersNativeNotebooksStateKeys.ShowBanner,
                true,
                InsidersDelayUntilNotified * months
            )
            .updateValue(false);
    }

    public async launchSurvey(): Promise<void> {
        this.browserService.launch(this.surveyLink);
    }

    private getOpenNotebookCount(): number {
        const state = this.persistentState.createGlobalPersistentState<number>(
            InsidersNativeNotebooksStateKeys.OpenNotebookCount,
            0
        );
        return state.value;
    }

    private getExecutionCount(): number {
        const state = this.persistentState.createGlobalPersistentState<number>(
            InsidersNativeNotebooksStateKeys.ExecutionCount,
            0
        );
        return state.value;
    }

    private async openedNotebook() {
        const state = this.persistentState.createGlobalPersistentState<number>(
            InsidersNativeNotebooksStateKeys.OpenNotebookCount,
            0
        );
        await state.updateValue(state.value + 1);
        return this.showBanner();
    }
}

