'use strict';

// tslint:disable:no-any max-func-body-length

import { expect } from 'chai';
import { instance, mock, when } from 'ts-mockito';
import * as typemoq from 'typemoq';
import { EventEmitter } from 'vscode';
import { Channel, IApplicationEnvironment, IApplicationShell } from '../../client/common/application/types';
import { Experiments } from '../../client/common/experiments/groups';
import { IBrowserService, IExperimentService, IPersistentState, IPersistentStateFactory } from '../../client/common/types';
import {
    InsidersNativeNotebooksStateKeys,
    InsidersNativeNotebooksSurveyBanner
} from '../../client/datascience/insidersNativeNotebookSurveyBanner';
import { NativeEditorProvider } from '../../client/datascience/notebookStorage/nativeEditorProvider';
import { INotebookEditor } from '../../client/datascience/types';

suite('Insiders Native Notebooks Survey Banner', () => {
    let appShell: typemoq.IMock<IApplicationShell>;
    let browser: typemoq.IMock<IBrowserService>;
    let experimentService: typemoq.IMock<IExperimentService>;
    let appEnvironment: typemoq.IMock<IApplicationEnvironment>;

    const message = 'Can you please take a minute to tell us about your notebooks experience in VS Code?';
    const yes = 'Yes, take survey now';
    const no = 'No, thanks';
    const surveyLink = 'https://aka.ms/vscjupyternb';

    setup(() => {
        appShell = typemoq.Mock.ofType<IApplicationShell>();
        browser = typemoq.Mock.ofType<IBrowserService>();
        experimentService = typemoq.Mock.ofType<IExperimentService>();
        appEnvironment = typemoq.Mock.ofType<IApplicationEnvironment>();
    });
    test('Insiders native notebooks survey banner should be shown after we hit our execution count', async () => {
        const enabledValue: boolean = true;
        const executionCount: number = 1000;
        const testBanner: InsidersNativeNotebooksSurveyBanner = preparePopup(
            executionCount,
            0,
            enabledValue,
            'insiders',
            appShell.object,
            browser.object,
            experimentService.object,
            appEnvironment.object
        );
        appShell
            .setup((a) =>
                a.showInformationMessage(typemoq.It.isValue(message), typemoq.It.isValue(yes), typemoq.It.isValue(no))
            )
            .returns(() => Promise.resolve(undefined))
            .verifiable(typemoq.Times.atLeastOnce());
        experimentService
            .setup((e) => e.inExperiment(typemoq.It.isValue(Experiments.NativeNotebook)))
            .returns(() => Promise.resolve(true));
        await testBanner.showBanner();
        appShell.verifyAll();
    });

    test('Insiders native notebooks survey banner should be shown after we hit our notebook count', async () => {
        const enabledValue: boolean = true;
        const testBanner: InsidersNativeNotebooksSurveyBanner = preparePopup(
            0,
            15,
            enabledValue,
            'insiders',
            appShell.object,
            browser.object,
            experimentService.object,
            appEnvironment.object
        );
        appShell
            .setup((a) =>
                a.showInformationMessage(typemoq.It.isValue(message), typemoq.It.isValue(yes), typemoq.It.isValue(no))
            )
            .returns(() => Promise.resolve(undefined))
            .verifiable(typemoq.Times.atLeastOnce());
        experimentService
            .setup((e) => e.inExperiment(typemoq.It.isValue(Experiments.NativeNotebook)))
            .returns(() => Promise.resolve(true));
        await testBanner.showBanner();
        appShell.verifyAll();
    });

    test('Do not show insiders native notebooks survey banner when channel is stable', async () => {
        const enabledValue: boolean = true;
        const executionCount: number = 1000;
        const testBanner: InsidersNativeNotebooksSurveyBanner = preparePopup(
            executionCount,
            0,
            enabledValue,
            'stable',
            appShell.object,
            browser.object,
            experimentService.object,
            appEnvironment.object
        );
        appShell
            .setup((a) =>
                a.showInformationMessage(typemoq.It.isValue(message), typemoq.It.isValue(yes), typemoq.It.isValue(no))
            )
            .verifiable(typemoq.Times.never());
        experimentService
            .setup((e) => e.inExperiment(typemoq.It.isValue(Experiments.NativeNotebook)))
            .returns(() => Promise.resolve(true));
        await testBanner.showBanner();
        appShell.verifyAll();
    });

    test('Do not show insiders native notebooks survey banner when the experiment flag is off', async () => {
        const enabledValue: boolean = true;
        const executionCount: number = 1000;
        const testBanner: InsidersNativeNotebooksSurveyBanner = preparePopup(
            executionCount,
            0,
            enabledValue,
            'insiders',
            appShell.object,
            browser.object,
            experimentService.object,
            appEnvironment.object
        );
        appShell
            .setup((a) =>
                a.showInformationMessage(typemoq.It.isValue(message), typemoq.It.isValue(yes), typemoq.It.isValue(no))
            )
            .verifiable(typemoq.Times.never());
        experimentService
            .setup((e) => e.inExperiment(typemoq.It.isValue(Experiments.NativeNotebook)))
            .returns(() => Promise.resolve(false));
        await testBanner.showBanner();
        appShell.verifyAll();
    });

    test('Do not show insiders native notebooks survey banner when disabled in persistent state', async () => {
        const enabledValue: boolean = false;
        const executionCount: number = 1000;
        const testBanner: InsidersNativeNotebooksSurveyBanner = preparePopup(
            executionCount,
            0,
            enabledValue,
            'insiders',
            appShell.object,
            browser.object,
            experimentService.object,
            appEnvironment.object
        );
        appShell
            .setup((a) =>
                a.showInformationMessage(typemoq.It.isValue(message), typemoq.It.isValue(yes), typemoq.It.isValue(no))
            )
            .verifiable(typemoq.Times.never());
        experimentService
            .setup((e) => e.inExperiment(typemoq.It.isValue(Experiments.NativeNotebook)))
            .returns(() => Promise.resolve(true));
        await testBanner.showBanner();
        appShell.verifyAll();
    });

    test('Do not show insiders native notebooks survey banner if we have not hit our execution count or notebook count', async () => {
        const enabledValue: boolean = true;
        const testBanner: InsidersNativeNotebooksSurveyBanner = preparePopup(
            99,
            4,
            enabledValue,
            'insiders',
            appShell.object,
            browser.object,
            experimentService.object,
            appEnvironment.object
        );
        appShell
            .setup((a) =>
                a.showInformationMessage(typemoq.It.isValue(message), typemoq.It.isValue(yes), typemoq.It.isValue(no))
            )
            .verifiable(typemoq.Times.never());
        experimentService
            .setup((e) => e.inExperiment(typemoq.It.isValue(Experiments.NativeNotebook)))
            .returns(() => Promise.resolve(true));
        await testBanner.showBanner();
        appShell.verifyAll();
    });

    test('Insiders native notebooks survey banner should launch the correct URL', async () => {
        const enabledValue: boolean = true;
        const testBanner: InsidersNativeNotebooksSurveyBanner = preparePopup(
            1000,
            0,
            enabledValue,
            'insiders',
            appShell.object,
            browser.object,
            experimentService.object,
            appEnvironment.object
        );
        let receivedUri: string = '';
        browser
            .setup((b) =>
                b.launch(
                    typemoq.It.is((a: string) => {
                        receivedUri = a;
                        return a === surveyLink;
                    })
                )
            )
            .verifiable(typemoq.Times.once());
        await testBanner.launchSurvey();
        expect(receivedUri).is.equal(surveyLink, 'Uri given to launch mock is incorrect.');

        browser.verifyAll();
        browser.reset();
    });
});

function preparePopup(
    executionCount: number,
    initialOpenCount: number,
    enabledValue: boolean,
    channel: Channel,
    appShell: IApplicationShell,
    browser: IBrowserService,
    experimentService: IExperimentService,
    appEnvironment: IApplicationEnvironment
): InsidersNativeNotebooksSurveyBanner {
    let openCount = 0;
    const myfactory: typemoq.IMock<IPersistentStateFactory> = typemoq.Mock.ofType<IPersistentStateFactory>();
    const enabledValState: typemoq.IMock<IPersistentState<boolean>> = typemoq.Mock.ofType<IPersistentState<boolean>>();
    const executionCountState: typemoq.IMock<IPersistentState<number>> = typemoq.Mock.ofType<
        IPersistentState<number>
    >();
    const openCountState: typemoq.IMock<IPersistentState<number>> = typemoq.Mock.ofType<IPersistentState<number>>();
    const provider = mock(NativeEditorProvider);
    (instance(provider) as any).then = undefined;
    const openedEventEmitter = new EventEmitter<INotebookEditor>();
    when(provider.onDidOpenNotebookEditor).thenReturn(openedEventEmitter.event);
    appEnvironment.setup((a) => a.channel).returns(() => channel);
    enabledValState
        .setup((a) => a.updateValue(typemoq.It.isValue(false)))
        .returns(() => Promise.resolve());

    executionCountState
        .setup((a) => a.updateValue(typemoq.It.isAnyNumber()))
        .returns(() => Promise.resolve());
    openCountState
        .setup((a) => a.updateValue(typemoq.It.isAnyNumber()))
        .returns((v) => {
            openCount = v;
            return Promise.resolve();
        });

    enabledValState.setup((a) => a.value).returns(() => enabledValue);
    executionCountState.setup((a) => a.value).returns(() => executionCount);
    openCountState.setup((a) => a.value).returns(() => openCount);

    myfactory
        .setup((a) =>
            a.createGlobalPersistentState(
                typemoq.It.isValue(InsidersNativeNotebooksStateKeys.ShowBanner),
                typemoq.It.isValue(true),
                typemoq.It.isAny()
            )
        )
        .returns(() => {
            return enabledValState.object;
        });
    myfactory
        .setup((a) =>
            a.createGlobalPersistentState(
                typemoq.It.isValue(InsidersNativeNotebooksStateKeys.ShowBanner),
                typemoq.It.isValue(false),
                typemoq.It.isAny()
            )
        )
        .returns(() => {
            return enabledValState.object;
        });
    myfactory
        .setup((a) =>
            a.createGlobalPersistentState(
                typemoq.It.isValue(InsidersNativeNotebooksStateKeys.ExecutionCount),
                typemoq.It.isAnyNumber()
            )
        )
        .returns(() => {
            return executionCountState.object;
        });
    myfactory
        .setup((a) =>
            a.createGlobalPersistentState(
                typemoq.It.isValue(InsidersNativeNotebooksStateKeys.OpenNotebookCount),
                typemoq.It.isAnyNumber()
            )
        )
        .returns(() => {
            return openCountState.object;
        });
    const result = new InsidersNativeNotebooksSurveyBanner(
        appShell,
        myfactory.object,
        browser,
        experimentService,
        appEnvironment,
        instance(provider)
    );

    // Fire the number of opens specified so that it behaves like the real editor
    for (let i = 0; i < initialOpenCount; i += 1) {
        openedEventEmitter.fire({} as any);
    }

    return result;
}

